mapper.update:
UPDATE crm_customer_privacy_request
SET status = 'REJECTED',
    reviewed_by = #{reviewedBy},
    reviewed_at = #{reviewedAt},
    review_reason = #{reviewReason},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND version = #{expectedVersion}
  AND status = 'PENDING'

UPDATE crm_customer_privacy_request
SET status = 'CANCELED',
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND version = #{expectedVersion}
  AND status = 'PENDING'

UPDATE crm_customer_privacy_request
SET status = 'REVOKED',
    revoked_by = #{revokedBy},
    revoked_at = #{revokedAt},
    revoke_reason = #{revokeReason},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND version = #{expectedVersion}
  AND status = 'APPROVED'

UPDATE crm_customer_privacy_request
SET reveal_count = reveal_count + 1,
    last_revealed_at = #{revealedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'APPROVED'

